do $$ declare t text; p text; begin foreach t in array array['leads','service_requests','invoices'] loop foreach p in array array['INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER'] loop if has_table_privilege('authenticated','public.'||t,p) or has_table_privilege('anon','public.'||t,p) then raise exception 'unexpected write grant: % %',t,p; end if; end loop; if not has_table_privilege('authenticated','public.'||t,'SELECT') or has_table_privilege('anon','public.'||t,'SELECT') then raise exception 'unexpected read grant: %',t; end if; end loop; end $$; select 'PASS: three REST tables read-only for authenticated, no anonymous access' as result;